    if slot_index < self.header.start_index {
        return false;
    }
    if slot_index >= self.header.start_index + super::BLOCK_CAP {
        return false;
    }

    let offset = offset(slot_index);
    let ready_bits = self.header.ready_slots.load(Acquire);
