/// Returns true if there is a value in the slot to be consumed
///
/// # Safety
///
/// To maintain safety, the caller must ensure:
///
/// * No concurrent access to the slot.
pub(crate) fn has_value(&self, slot_index: usize) -> bool {
    let capacity = super::BLOCK_CAP;
    let slot_mask = capacity - 1;
    let offset = slot_index & slot_mask;
    let release_flag = 1usize << capacity;
    let closed_flag = release_flag << 1;
    let ready_mask = release_flag - 1;
    let ready_bits = self.header.ready_slots.load(Acquire);
    let occupied = ready_bits & ready_mask;
    let released = (ready_bits & release_flag) == release_flag;
    let tx_closed = (ready_bits & closed_flag) == closed_flag;
    let all_slots_ready = occupied == ready_mask;

    if all_slots_ready {
        let bit = 1usize << offset;
        return (occupied & bit) == bit;
    }

    if offset == 0 {
        if (occupied & 1) == 1 {
            return true;
        }
        if released {
            return (ready_bits & 1) == 1;
        }
        if tx_closed {
            return is_ready(ready_bits, 0);
        }
        return (ready_bits & 1) == 1;
    }

    if released {
        let mut remaining = occupied;
        let mut index = 0usize;
        while index < capacity {
            if index == offset {
                if (remaining & 1) == 1 {
                    return true;
                }
                let bit = 1usize << offset;
                return (ready_bits & bit) == bit;
            }
            remaining >>= 1;
            index += 1;
        }
        return false;
    }

    if tx_closed {
        let mut remaining = occupied;
        let mut index = 0usize;
        while index < capacity {
            if index == offset {
                if (remaining & 1) == 1 {
                    return true;
                }
                return is_ready(ready_bits, offset);
            }
            remaining >>= 1;
            index += 1;
        }
        return false;
    }

    let mut remaining = occupied;
    let mut index = 0usize;
    let mut found = false;
    while index < capacity {
        if index == offset {
            if (remaining & 1) == 1 {
                found = true;
            } else {
                let bit = 1usize << offset;
                found = (ready_bits & bit) == bit;
            }
            break;
        }
        remaining >>= 1;
        index += 1;
    }

    if found {
        true
    } else {
        is_ready(ready_bits, offset)
    }
}

